/**
 * Errors raised when a business rule or invariant of the domain is violated.
 */
export abstract class DomainError extends Error {
  protected constructor(message: string) {
    super(message);
    this.name = new.target.name;
  }
}

/** A value supplied to the domain does not satisfy its rules (e.g. a negative quantity). */
export class InvalidValueError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

export interface StockShortage {
  readonly productId: string;
  readonly requested: number;
  readonly available: number;
}

/** One or more products cannot cover the requested quantities. */
export class InsufficientStockError extends DomainError {
  constructor(readonly shortages: readonly StockShortage[]) {
    super(
      `Insufficient stock for ${shortages
        .map((s) => `${s.productId} (requested ${s.requested}, available ${s.available})`)
        .join(', ')}`,
    );
  }
}

/** An order was asked to move to a state that is not reachable from its current state. */
export class InvalidOrderTransitionError extends DomainError {
  constructor(
    readonly orderId: string,
    readonly from: string,
    readonly to: string,
  ) {
    super(`Order ${orderId} cannot move from '${from}' to '${to}'`);
  }
}

/** Reserved stock bookkeeping would become inconsistent; indicates a programming error. */
export class StockAccountingError extends DomainError {
  constructor(message: string) {
    super(message);
  }
}

